<script setup lang="ts">
import {computed,ref} from 'vue'
import {useWorkspace} from '../workspace'
import type {ServiceRule} from '../domain'
import {unlockGroups,unlockGroup,unlockSupported} from '../unlock'
const props=defineProps<{modelValue:string[];catalog:ServiceRule[]}>(),emit=defineEmits<{'update:modelValue':[value:string[]]}>(),search=ref(''),customName=ref('')
const w=useWorkspace()
const customKey='cst.custom-unlock-groups'
interface CustomUnlockGroup{id:string;name:string;ids:string[]}
function loadCustomGroups():CustomUnlockGroup[]{try{const raw=window.localStorage.getItem(customKey),parsed=raw?JSON.parse(raw):[];return Array.isArray(parsed)?parsed.filter((g):g is CustomUnlockGroup=>!!g&&typeof g.id==='string'&&typeof g.name==='string'&&Array.isArray(g.ids)):[]}catch{return []}}
const customGroups=ref<CustomUnlockGroup[]>(loadCustomGroups())
function persistCustomGroups(){try{window.localStorage.setItem(customKey,JSON.stringify(customGroups.value))}catch{}}
const selectable=computed(()=>props.catalog.filter(s=>!s.superseded_by&&unlockGroup(s.service_id)!=='legacy'))
const visible=computed(()=>selectable.value.filter(s=>!search.value||(s.name+' '+s.description).toLowerCase().includes(search.value.trim().toLowerCase())))
function toggle(id:string){emit('update:modelValue',props.modelValue.includes(id)?props.modelValue.filter(s=>s!==id):[...props.modelValue,id])}
function groupIds(id:string){const custom=customGroups.value.find(g=>g.id===id);if(custom)return custom.ids.filter(cid=>selectable.value.some(s=>s.service_id===cid&&unlockSupported(s.service_id)));return selectable.value.filter(s=>s.service_id!=='antigravity'&&unlockGroup(s.service_id)===id&&unlockSupported(s.service_id)).map(s=>s.service_id)}
function toggleGroup(id:string,checked:boolean){const ids=groupIds(id);emit('update:modelValue',checked?[...new Set([...props.modelValue,...ids])]:props.modelValue.filter(s=>!ids.includes(s)))}
function saveCustomGroup(){const ids=props.modelValue.filter(id=>selectable.value.some(s=>s.service_id===id&&unlockSupported(s.service_id)));if(!ids.length)return;const name=(customName.value||'').trim()||'自定义';const existing=customGroups.value.find(g=>g.name===name);if(existing)existing.ids=[...ids];else customGroups.value.push({id:`custom-${Date.now().toString(36)}`,name,ids:[...ids]});customName.value='';persistCustomGroups()}
function removeCustomGroup(id:string){customGroups.value=customGroups.value.filter(g=>g.id!==id);persistCustomGroups()}
const allGroups=computed(()=>[...unlockGroups.map(g=>({...g,custom:false})),...customGroups.value.map(g=>({...g,custom:true}))])
</script>
<template><div class="service-picker unlock-picker">
 <div class="unlock-group-options"><label v-for="g in allGroups" :key="g.id"><input type="checkbox" :checked="groupIds(g.id).length>0&&groupIds(g.id).every(id=>modelValue.includes(id))" :indeterminate="groupIds(g.id).some(id=>modelValue.includes(id))&&!groupIds(g.id).every(id=>modelValue.includes(id))" @change="toggleGroup(g.id,($event.target as HTMLInputElement).checked)"><strong>{{g.name}}</strong><small>{{groupIds(g.id).length}} 项</small><button v-if="g.custom" type="button" class="text-button unlock-group-remove" :aria-label="`删除自定义分组 ${g.name}`" title="删除此分组" @click.prevent.stop="removeCustomGroup(g.id)">×</button></label></div>
 <label class="unlock-region-toggle"><input v-model="w.skipByApplicableRegions.value" type="checkbox">按适用地区跳过</label>
 <details class="unlock-custom"><summary>展开自定义 <small>已选 {{modelValue.length}} 项</small></summary><div class="unlock-custom-bar"><input v-model="search" type="search" aria-label="搜索检测服务" placeholder="搜索解锁项目"><div class="unlock-custom-save"><input v-model="customName" type="text" aria-label="自定义分组名称" placeholder="保存为分组（默认：自定义）"><button type="button" class="button" :disabled="!modelValue.length" @click="saveCustomGroup">保存分组</button></div></div><div class="service-picker-list"><label v-for="s in visible" :key="s.service_id" :class="{checked:modelValue.includes(s.service_id)}" :title="s.description"><input type="checkbox" :checked="modelValue.includes(s.service_id)" :disabled="!unlockSupported(s.service_id)" @change="toggle(s.service_id)"><span><strong>{{s.name}}{{!unlockSupported(s.service_id)?' · 暂不支持':''}}</strong><small>{{s.description}}</small></span></label></div></details>
</div></template>
<style scoped>.unlock-region-toggle{display:flex;align-items:center;gap:7px;margin-top:12px;font-size:12px}.unlock-region-toggle input{width:15px;height:15px}.unlock-group-options{display:flex;gap:8px;flex-wrap:wrap}.unlock-group-options label{display:flex;align-items:center;gap:8px;padding:9px 13px;border:1px solid var(--line);border-radius:10px;background:var(--surface);flex:1 1 130px;min-width:0;cursor:pointer;transition:border-color .14s,background .14s}.unlock-group-options label:hover{border-color:var(--blue)}.unlock-group-options strong{overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:12.5px}.unlock-group-options small,.unlock-custom small{color:var(--muted);font-size:11px;white-space:nowrap}.unlock-group-options input{width:15px;height:15px;flex:none}.unlock-group-remove{margin-left:auto;padding:0 4px;font-size:14px;line-height:1;color:var(--muted)}.unlock-custom{margin-top:12px}.unlock-custom summary{font-size:12px;cursor:pointer}.unlock-custom-bar{display:flex;gap:10px;flex-wrap:wrap;align-items:center;margin:12px 0}.unlock-custom-bar>input{flex:1 1 180px;min-width:0}.unlock-custom-save{display:flex;gap:8px;align-items:center;flex:1 1 220px;min-width:0}.unlock-custom-save input{flex:1;min-width:0}</style>
